#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long k;
    cin >> n >> k;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    sort(a.begin(), a.end());
    long long i = 0;
    while (i < n && i < k && a[i] < 0) {
        a[i] = -a[i];
        i++;
    }
    long long rest = k - i, total = 0, smallest = a[0];
    for (long long x : a) {
        total += x;
        smallest = min(smallest, x);
    }
    if (rest % 2 == 1) total -= 2 * smallest;
    cout << total << "\n";

    return 0;
}

